effect.shader:

precision highp float;
in vec2 fragCoord;
out vec4 fragColor;
uniform sampler2D uTexture;
uniform float rows;
uniform float cols;
uniform float multiplier;
uniform float rotation;
uniform float random;

void main() {
    vec2 st = fragCoord;
    vec2 grid = vec2(cols, rows);
    vec2 ipos = floor(st * grid);
    vec2 fpos = fract(st * grid);

    // Calculate pseudo-random offset per card
    float randID = fract(sin(dot(ipos, vec2(12.9898, 78.233) + random)) * 43758.5453);

    vec2 offset = (randID - 0.5) * (multiplier * 0.001);
    vec2 uv = st + offset;

    vec4 color = texture(uTexture, uv);
    fragColor = color;
}
